// means unrestricted (Admin). Mirrors ListK8sPodsForClusterResourceIDs
// exactly, generalized over `kind`.
func (q *Queries) ListK8sResourcesForClusterResourceIDs(ctx context.Context, arg ListK8sResourcesForClusterResourceIDsParams) ([]ListK8sResourcesForClusterResourceIDsRow, error) {
	rows, err := q.db.Query(ctx, listK8sResourcesForClusterResourceIDs, arg.Kind, arg.ResourceIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListK8sResourcesForClusterResourceIDsRow{}
	for rows.Next() {
		var i ListK8sResourcesForClusterResourceIDsRow
		if err := rows.Scan(
			&i.ID,
			&i.K8sClusterID,
			&i.Kind,
			&i.Namespace,
			&i.Name,
			&i.Detail,
			&i.LastDiscoveredAt,
			&i.ClusterResourceID,
			&i.ClusterName,
			&i.WorkspaceID,
			&i.WorkspaceName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

